import{_ as s,o as p,a as n,b as e}from"./app.DKoEZOcr.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"guide/operator_practice/typical_operator_cases/simd_operator_impl/matmul_leakyrelu_fusion_operator/extreme_optimization.md","filePath":"guide/operator_practice/typical_operator_cases/simd_operator_impl/matmul_leakyrelu_fusion_operator/extreme_optimization.md","outlineHeaders":[{"level":2,"title":"Matmul高阶优化手段","slug":"Matmul高阶优化手段","link":"#Matmul高阶优化手段"},{"level":2,"title":"Gelu高阶优化手段","slug":"Gelu高阶优化手段","link":"#Gelu高阶优化手段"},{"level":2,"title":"CV融合：Scenario 2 — CV融合-UB直通","slug":"CV融合：Scenario-2-—-CV融合-UB直通","link":"#CV融合：Scenario-2-—-CV融合-UB直通"},{"level":3,"title":"性能数据","slug":"性能数据","link":"#性能数据"}],"lastUpdated":1787050286000}'),t={name:"guide/operator_practice/typical_operator_cases/simd_operator_impl/matmul_leakyrelu_fusion_operator/extreme_optimization.md"};function c(l,a,i,o,r,d){return p(),n("div",null,[...a[0]||(a[0]=[e(`<div><article class="markdown-body"><h1>高阶极限打磨<span id="ZH-CN_TOPIC_000000_MATMUL_LEAKYRELU_ADV"></span></h1><p>本节在中级性能优化的基础上，介绍Matmul融合算子的高阶极限打磨方法。</p><blockquote><p><strong>说明</strong>：为更好展示VF融合的性能优化手段，本章节以Matmul+Gelu融合算子作为讲解样例。GELU相比LeakyRelu计算逻辑更复杂，能更充分地体现各类优化手段的效果。</p></blockquote><h2 id="Matmul高阶优化手段">Matmul高阶优化手段<a class="header-anchor" href="#Matmul高阶优化手段">​</a></h2><table><thead><tr><th>Case</th><th>优化手段</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_high_performance/README.md#case-5-%E5%A4%9A%E6%A0%B8mdl--l1cache%E4%BC%98%E5%8C%96-multi_core_mdl_l1cache">Case 5</a></td><td>MDL + L1Cache优化</td><td>手动调整Tiling参数，充分利用L1缓存</td></tr><tr><td><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_high_performance/README.md#case-6-%E5%A4%9A%E6%A0%B8mdl--l1cache--l2cache-multi_core_mdl_l1cache_l2cache">Case 6</a></td><td>MDL + L1Cache + L2Cache</td><td>分块计算适配L2Cache，提高缓存命中率</td></tr><tr><td><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_high_performance/README.md#case-7-%E5%A4%9A%E6%A0%B8mdl--l1cache--l2cache--constants-tiling-multi_core_mdl_l1cache_l2cache_constants">Case 7</a></td><td>+ Constants Tiling</td><td>Tiling常量化，减少运行时Scalar计算开销</td></tr><tr><td><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/01_matrix_compute/matmul_high_performance/README.md#case-8-%E5%A4%9A%E6%A0%B8mdl--l1cache--l2cache--constants-tiling--unitflag-multi_core_mdl_l1cache_l2cache_constants_unitflag">Case 8</a></td><td>+ UnitFlag</td><td>细粒度流水同步，MMAD与FIXPIPE流水并行</td></tr></tbody></table><h2 id="Gelu高阶优化手段">Gelu高阶优化手段<a class="header-anchor" href="#Gelu高阶优化手段">​</a></h2><table><thead><tr><th>Case</th><th>优化手段</th><th>说明</th></tr></thead><tbody><tr><td><a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/02_reg_compute/gelu_high_performance/README.md#case-2-%E5%90%AF%E7%94%A8regbase-apivf%E8%9E%8D%E5%90%88%E8%83%BD%E5%8A%9B%E5%92%8C%E5%BE%AA%E7%8E%AF%E5%B1%95%E5%BC%80%E4%BC%98%E5%8C%96">Case 2</a></td><td>VF融合 + 循环展开</td><td><code>#pragma unroll</code>展开循环，提高指令级并行度</td></tr></tbody></table><h2 id="CV融合：Scenario-2-—-CV融合-UB直通">CV融合：Scenario 2 — CV融合-UB直通<a class="header-anchor" href="#CV融合：Scenario-2-—-CV融合-UB直通">​</a></h2><p>在高阶极限打磨阶段，CV融合层面提供Scenario 2方式（仅Ascend 950PR支持）。AIC侧通过Fixpipe将L0C计算结果直接写入Unified Buffer（UB），AIV侧无需从GM读取数据，直接在UB上进行GELU计算后将结果写回GM，省去GM中转的读写开销。</p><blockquote><p><strong>兼容性说明</strong>：A2/A3芯片不支持Fixpipe直写UB，请使用Scenario 1（CV融合-GM中转）方案。</p></blockquote><p>数据流路径：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>GM ──(MTE2)──&gt; L1 ──(MTE1)──&gt; L0A/L0B ──(Cube)──&gt; L0C ──(Fixpipe)──&gt; UB ──(Gelu)──&gt; UB ──(MTE3)──&gt; GM
</code></pre></div><p><strong>AIC侧实现</strong>：Fixpipe L0C → UB（通过<code>dualDstCtl=0b01</code>开启双目标模式，按M维度拆分给2个AIV）</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">FixpipeParamsArch3510</span><span class="o">&lt;</span><span class="n">AscendC</span><span class="o">::</span><span class="n">CO2Layout</span><span class="o">::</span><span class="n">ROW_MAJOR</span><span class="o">&gt;</span><span class="w"> </span><span class="n">fixpipeParams</span><span class="p">;</span>
<span class="n">fixpipeParams</span><span class="p">.</span><span class="n">mSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">DivCeil</span><span class="p">(</span><span class="n">curM</span><span class="p">,</span><span class="w"> </span><span class="mi">2</span><span class="p">)</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="n">fixpipeParams</span><span class="p">.</span><span class="n">nSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">curN</span><span class="p">;</span>
<span class="n">fixpipeParams</span><span class="p">.</span><span class="n">srcStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">curMAlign</span><span class="p">;</span>
<span class="n">fixpipeParams</span><span class="p">.</span><span class="n">dstStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">curN</span><span class="p">;</span>
<span class="n">fixpipeParams</span><span class="p">.</span><span class="n">dualDstCtl</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mb">0b01</span><span class="p">;</span><span class="w">  </span><span class="c1">// 按M维度拆分到2个AIV的UB</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Fixpipe</span><span class="o">&lt;</span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="kt">float</span><span class="p">,</span><span class="w"> </span><span class="n">CFG_ROW_MAJOR_UB</span><span class="o">&gt;</span><span class="p">(</span><span class="n">xUB</span><span class="p">,</span><span class="w"> </span><span class="n">cLocal</span><span class="p">,</span><span class="w"> </span><span class="n">fixpipeParams</span><span class="p">);</span>
</code></pre></div><p><strong>AIV侧实现</strong>：UB → GELU → geluOutUB → GM（无需DataCopy GM→UB）</p><h3 id="性能数据">性能数据<a class="header-anchor" href="#性能数据">​</a></h3><p>以Ascend 950PR芯片数据为例：</p><ul><li>Scenario 2融合后总耗时2573.584μs，相比Scenario 1的2606.91μs进一步减少约33μs</li><li>Scenario 2中aiv_mte2_time仅为0.005μs，相比Scenario 1的57.145μs几乎降为零</li></ul><p>详细内容请参见<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/05_best_practices/03_fusion_compute/matmul_gelu_high_performance/README.md">Matmul+Gelu高阶极限打磨</a>。</p></article></div>`,1)])])}const h=s(t,[["render",c]]);export{m as __pageData,h as default};
